-- GX350 deferred IRI identity: after GX333 and scoped readback.
-- No historical data mutation, grants or new RPC. Insertion proof is
-- generated by the actual insert inside the legacy helper, not by callers.
DO $gx350_iri$
DECLARE
  direction constant text:='__GX350_READBACK_DIRECTION__';
  step record;
  patch record;
  prior text;
  revised text;
  source_anchor text;
  dest_anchor text;
  source_md5 text;
  dest_md5 text;
  prior_meta jsonb;
  revised_meta jsonb;
BEGIN
  IF direction NOT IN ('install','rollback') THEN RAISE EXCEPTION 'GX350_IRI_DIRECTION_INVALID'; END IF;
  FOR step IN SELECT * FROM (VALUES
    ('public.iberfit_create_client_draft_v12_pre_v65e(jsonb)'::regprocedure,'5eca7c696f69e01a25d1d56f053974ce','3f9dcbdc0ad2e0ed522ca8879e952327',jsonb_build_array(jsonb_build_array($a00$  v_iri_available boolean:=false;$a00$,$b00$  v_iri_available boolean:=false;
  gx350_iri_inserted boolean:=false;$b00$),
jsonb_build_array($a01$      'iri-protocols-2026.07-v1','contexto',clock_timestamp()
    );$a01$,$b01$      'iri-protocols-2026.07-v1','contexto',clock_timestamp()
    );
    gx350_iri_inserted:=true;$b01$),
jsonb_build_array($a02$    'iri_entity_available',true,'iri_id',v_iri_id,'version','v12.3'
  );$a02$,$b02$    'iri_entity_available',true,'iri_id',v_iri_id,'version','v12.3'
  ) || case when v_actor_role='admin' and p_payload->>'entryIntent'='training'
      and p_payload->>'initialAssessmentMode'='deferred'
      then jsonb_build_object('gx350IriInserted',gx350_iri_inserted)
      else '{}'::jsonb end;$b02$)),1),
    ('public.iberfit_admin_create_client_v26_pre_privileged_assurance(jsonb,jsonb)'::regprocedure,'0e37c22b36d6686b308d228f3c476216','28bc27a71735b1cd5f540cb2c03d07d9',jsonb_build_array(jsonb_build_array($a10$  return v_result;
end
$function$$a10$,$b10$  -- Only the exact assessment inserted by this transaction may be cleaned.
  -- Existing drafts, including a concurrent assessment, are never inferred
  -- from a client ID or from the absence of a prior row.
  if v_payload->>'entryIntent'='training'
     and v_payload->>'initialAssessmentMode'='deferred' then
    if v_created->>'gx350IriInserted' not in ('true','false')
       or v_created->>'gx350IriInserted' is null then
      raise exception 'GX350_IRI_INSERTION_PROOF_MISSING';
    end if;
    if v_created->>'gx350IriInserted'='true' then
      if coalesce(v_created->>'iri_entity_available','false')<>'true'
         or nullif(v_created->>'iri_id','') is null then
        raise exception 'GX350_NEW_IRI_PLACEHOLDER_ID_MISSING';
      end if;
      return v_result||jsonb_build_object('iri_id',v_created->'iri_id','iri_entity_available',true);
    end if;
  end if;
  return v_result;
end
$function$$b10$)),2),
    ('public.iberfit_admin_create_client_v26(jsonb,jsonb)'::regprocedure,'58dbd5687c5547e8c4ba2cbad9974f75','4c6c90e380103da84e4076e13e40dd8b',jsonb_build_array(jsonb_build_array($a20$  if v_entry='training' and v_assessment='deferred' and not v_had_iri then$a20$,$b20$  if v_entry='training' and v_assessment='deferred' and v_result ? 'iri_id' then$b20$),
jsonb_build_array($a21$  v_result:=v_result-'relationshipType'-'initialLifecycleStatus';
  if v_assessment='deferred' and v_cleaned_placeholder then$a21$,$b21$  -- Fail closed if a new transaction-owned placeholder was not removed.
  -- Never delete an earlier or unrelated assessment; an already existing
  -- IRI is valid for an intentionally reused expediente.
  if v_entry='training' and v_assessment='deferred' then
    if (v_result ? 'iri_id') and not v_cleaned_placeholder then
      raise exception 'GX350_DEFERRED_IRI_CLEANUP_UNCONFIRMED';
    end if;
    if v_existing_person is null and not v_cleaned_placeholder then
      raise exception 'GX350_NEW_DEFERRED_IRI_CLEANUP_UNCONFIRMED';
    end if;
    if v_cleaned_placeholder and (exists(
      select 1 from public.iri_assessments where id=v_created_iri
    ) or exists(
      select 1 from public.domain_entities_v26 where entity_type='iri' and entity_id=v_created_iri
    )) then raise exception 'GX350_DEFERRED_IRI_RESIDUAL'; end if;
  end if;
  v_result:=v_result-'relationshipType'-'initialLifecycleStatus';
  if v_assessment='deferred' and v_cleaned_placeholder then$b21$)),3)
  ) s(signature,old_md5,new_md5,patches,ordinal)
    ORDER BY CASE WHEN direction='install' THEN ordinal ELSE -ordinal END
  LOOP
    source_md5:=CASE WHEN direction='install' THEN step.old_md5 ELSE step.new_md5 END;
    dest_md5:=CASE WHEN direction='install' THEN step.new_md5 ELSE step.old_md5 END;
    prior:=pg_get_functiondef(step.signature);
    IF md5(prior) IS DISTINCT FROM source_md5 THEN RAISE EXCEPTION 'GX350_IRI_SOURCE_DRIFT'; END IF;
    IF has_function_privilege('anon',step.signature,'EXECUTE') OR has_function_privilege('authenticated',step.signature,'EXECUTE') THEN
      RAISE EXCEPTION 'GX350_IRI_INTERNAL_ACL_DRIFT';
    END IF;
    SELECT to_jsonb(p)-'prosrc' INTO prior_meta FROM pg_proc p WHERE p.oid=step.signature::oid;
    revised:=prior;
    FOR patch IN SELECT value,ordinality FROM jsonb_array_elements(step.patches) WITH ORDINALITY
      ORDER BY CASE WHEN direction='install' THEN ordinality ELSE -ordinality END
    LOOP
      source_anchor:=patch.value->>CASE WHEN direction='install' THEN 0 ELSE 1 END;
      dest_anchor:=patch.value->>CASE WHEN direction='install' THEN 1 ELSE 0 END;
      IF (length(revised)-length(replace(revised,source_anchor,'')))/length(source_anchor)<>1 THEN RAISE EXCEPTION 'GX350_IRI_ANCHOR_DRIFT'; END IF;
      revised:=replace(revised,source_anchor,dest_anchor);
    END LOOP;
    IF md5(revised) IS DISTINCT FROM dest_md5 THEN RAISE EXCEPTION 'GX350_IRI_TARGET_DRIFT'; END IF;
    EXECUTE revised;
    SELECT to_jsonb(p)-'prosrc' INTO revised_meta FROM pg_proc p WHERE p.oid=step.signature::oid;
    IF md5(pg_get_functiondef(step.signature)) IS DISTINCT FROM dest_md5 OR prior_meta IS DISTINCT FROM revised_meta THEN
      RAISE EXCEPTION 'GX350_IRI_CATALOG_DRIFT';
    END IF;
  END LOOP;
END $gx350_iri$;
